import admin from "firebase-admin";

if (!admin.apps.length) {
  admin.initializeApp({
    credential: admin.credential.cert({
      projectId: process.env.FIREBASE_PROJECT_ID,
      clientEmail: process.env.FIREBASE_CLIENT_EMAIL,
      privateKey: (process.env.FIREBASE_PRIVATE_KEY ?? "").replace(/\\n/g, "\n"),
    }),
  });
}

export const db = admin.firestore();
export const auth = admin.auth();

export async function getDoc<T>(collection: string, id: string): Promise<T | null> {
  const snap = await db.collection(collection).doc(id).get();
  if (!snap.exists) return null;
  return { id: snap.id, ...snap.data() } as T;
}

export async function setDoc(collection: string, id: string, data: Record<string, unknown>) {
  await db.collection(collection).doc(id).set(data, { merge: true });
}

export async function listDocs<T>(collection: string, limit = 100): Promise<T[]> {
  const snap = await db.collection(collection).limit(limit).get();
  return snap.docs.map((d) => ({ id: d.id, ...d.data() }) as T);
}
